static void p4wq_setup(void)
{
	/* Allow p4wq worker threads to run and self-pend */
	k_msleep(10);
	/* After this, all MAX_NUM_THREADS workers should be pended,
	 * so active_count() should be 0.
	 */
	zassert_equal(active_count(), 0, "p4wq workers not idle after setup");
}

